-- Pay Change -- authored as a DRAFT, 2026-11-13, TEST mode. APPLIED via psql 2026-11-13: form_id 54d31da1-4c93-4588-8bac-eaeab0c5eee8.
-- Replaces JotForms 250143453430041, 250143372028044, 250142790635960,
-- 250144363046045 and 251284153618053 (one process re-typed at every step).
-- Built by scripts/gen-pay-change.ts (strict + draft validated). In TEST mode
-- every approver and recipient is josh.copp@splashcarwashes.com. To go live,
-- regenerate with LIVE=1, write the schema into the open draft, and publish.
--
--   slug pay-change   audience link-only   30 fields   10 stages
--
-- Flow: GM request -> RM approve (signature) / deny (reason) -> RD (am_email)
-- approve / deny -> site link: employee signs + prints name -> PDF to payroll@
-- and the site email. Denials email the requesting manager and the site.
--
-- CONFIDENTIAL, NOT SITE-SCOPED: scope_location_field_key is set to the
-- sentinel 'none:confidential' so publish neither injects nor designates a
-- site_number scope field (admin/forms.ts handlePublish only acts while it is
-- NULL) and submit resolves no location (no field has that key). Submissions
-- are visible only to admins and the workflow's own people. Leave it until the
-- phase 3 access rule exists.
--
-- 2026-11-13 revision (operator feedback after testing): approval emails carry a
-- short summary instead of {payload.summary}; the NY notice section and the
-- manager's email are hide_from_approvers. Re-applied into the open draft.
--
-- 2026-11-13 revision 2: employee sign-off page says the EMPLOYEE signs
-- (page_intro, show_fields, employee labels); payroll email attaches the
-- official NY s.195.1 notice (attach_ny_pay_notice). The sign-off email's
-- button reads "Open for employee signature" (approval_link_label).
--
-- Re-runnable: upserts the forms row, creates a draft version only when there
-- is none, otherwise overwrites the existing draft schema.

insert into public.forms
  (slug, title, description, audience, status, notify_webhook,
   turnstile_required, success_message, created_by, last_edited_by)
values
  ('pay-change',
   'Pay Change',
   'Request a pay rate change for an employee. The RM and RD approve, the employee signs, and payroll gets the signed form.',
   'link-only',
   'draft',
   true,
   false,
   'Thanks - the pay change request has been sent to the regional manager.',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89')
on conflict (slug) do update
  set title = excluded.title,
      description = excluded.description,
      audience = excluded.audience,
      turnstile_required = excluded.turnstile_required,
      success_message = excluded.success_message,
      last_edited_at = now();

update public.forms set scope_location_field_key = 'none:confidential'
 where slug = 'pay-change' and scope_location_field_key is distinct from 'none:confidential';

