new_pay_type}\nEffective: {field.effective_date}\nMonthly cost: ${field.monthly_effect}\nLabor budget / trend: {field.labor_budget} / {field.labor_trend}\nBack pay: {field.back_pay}\nRequested by: {field.manager_name}\n\n{approval.link}","transitions":[{"to":"employee_signoff","label":"Sent"}]},{"id":"employee_signoff","label":"Employee acknowledgement","kind":"approval","approver_source":{"type":"static_emails","emails":["josh.copp@splashcarwashes.com"]},"page_intro":"Manager: hand this device to {field.employee}.\n\n{field.employee}: your pay rate is changing as shown below. Please review it, then type your name and sign to acknowledge that you have been told your new pay rate (and, in New York, your overtime rate, allowances and payday).","show_fields":["employee","site_name","current_rate","current_pay_type","new_rate","new_pay_type","effective_date","ny_payday","ny_pay_frequency","ny_allowances","ny_allowance_detail","ny_primary_language","ny_notice_language"],"transitions":[{"to":"payroll_email","label":"Sign and submit","requires":{"signature":true,"typed_name":true},"typed_name_label":"Employee''s full name","signature_label":"Employee signature"}]},{"id":"payroll_email","label":"Email payroll","kind":"email","recipients":[{"type":"static_emails","emails":["josh.copp@splashcarwashes.com"]}],"attach_pdf":true,"attach_ny_pay_notice":true,"subject_template":"[TEST] Approved pay change: {field.employee} at {field.site_name}","body_template":"Approved and signed pay change for {field.employee} at {field.site_name}.\n\nPay: ${field.current_rate} {field.current_pay_type} -> ${field.new_rate} {field.new_pay_type}\nEffective: {field.effective_date}\nMonthly cost: ${field.monthly_effect}\nLabor budget / trend: {field.labor_budget} / {field.labor_trend}\nBack pay: {field.back_pay}\nRequested by: {field.manager_name}\n\nThe signed form, with both approvals and the employee''s acknowledgement, is attached.","transitions":[{"to":"approved","label":"Sent"}]},{"id":"denied_email","label":"Email denial","kind":"email","recipients":[{"type":"static_emails","emails":["josh.copp@splashcarwashes.com"]}],"attach_pdf":true,"subject_template":"[TEST] Pay change denied: {field.employee} at {field.site_name}","body_template":"The pay change for {field.employee} at {field.site_name} was denied by {decision.by}.\n\nReason: {decision.note}\n\nPay: ${field.current_rate} {field.current_pay_type} -> ${field.new_rate} {field.new_pay_type}\nEffective: {field.effective_date}\nMonthly cost: ${field.monthly_effect}\nLabor budget / trend: {field.labor_budget} / {field.labor_trend}\nBack pay: {field.back_pay}\nRequested by: {field.manager_name}","transitions":[{"to":"denied","label":"Sent"}]},{"id":"approved","label":"Approved","kind":"outcome","tint":"success","transitions":[]},{"id":"denied","label":"Denied","kind":"outcome","tint":"danger","transitions":[]}]}}'::jsonb
  from public.forms f
 where f.slug = 'pay-change' and v.id = f.draft_version_id;

select f.id, f.slug, f.audience, f.status, f.scope_location_field_key,
       jsonb_array_length(v.schema->'fields') as fields,
       jsonb_array_length(v.schema->'workflow'->'stages') as stages
  from public.forms f
  join public.form_versions v on v.id = f.draft_version_id
 where f.slug = 'pay-change';
